insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-classic-novels-trivia',
  'Classic Novels Trivia: From Don Quixote to Jane Eyre',
  'Eight questions on the novels that built the canon: Don Quixote, Pride and Prejudice, Moby-Dick, Crime and Punishment and more.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"Who wrote Don Quixote, the founding novel of modern literature?","options":[{"id":"a","text":"Lope de Vega","is_correct":false},{"id":"b","text":"Miguel de Cervantes","is_correct":true},{"id":"c","text":"Calderón de la Barca","is_correct":false},{"id":"d","text":"Tirso de Molina","is_correct":false}],"explanation":"Cervantes published the first part of Don Quixote in 1605 and the second in 1615."},{"id":"q2","question":"In which year was the first part of Don Quixote published?","options":[{"id":"a","text":"1595","is_correct":false},{"id":"b","text":"1605","is_correct":true},{"id":"c","text":"1615","is_correct":false},{"id":"d","text":"1620","is_correct":false}],"explanation":"The first part appeared in 1605; the second followed a decade later, in 1615."},{"id":"q3","question":"Which English author wrote Pride and Prejudice, published in 1813?","options":[{"id":"a","text":"Charlotte Brontë","is_correct":false},{"id":"b","text":"Mary Shelley","is_correct":false},{"id":"c","text":"Jane Austen","is_correct":true},{"id":"d","text":"Emily Brontë","is_correct":false}],"explanation":"Austen published the novel anonymously, ''By a Lady''; her name became public after her death."},{"id":"q4","question":"Who wrote Moby-Dick, the 1851 novel about Captain Ahab''s hunt for the white whale?","options":[{"id":"a","text":"Nathaniel Hawthorne","is_correct":false},{"id":"b","text":"Herman Melville","is_correct":true},{"id":"c","text":"Edgar Allan Poe","is_correct":false},{"id":"d","text":"Mark Twain","is_correct":false}],"explanation":"Melville drew on his own whaling voyages; the novel sold poorly during his lifetime."},{"id":"q5","question":"In Dostoevsky''s Crime and Punishment (1866), what is the name of the student who commits the murder?","options":[{"id":"a","text":"Rodion Raskolnikov","is_correct":true},{"id":"b","text":"Prince Myshkin","is_correct":false},{"id":"c","text":"Nikolai Stavrogin","is_correct":false},{"id":"d","text":"Alyosha Karamazov","is_correct":false}],"explanation":"Raskolnikov kills a pawnbroker in Saint Petersburg; Myshkin is the hero of The Idiot."},{"id":"q6","question":"Which French author wrote Madame Bovary (1856)?","options":[{"id":"a","text":"Victor Hugo","is_correct":false},{"id":"b","text":"Émile Zola","is_correct":false},{"id":"c","text":"Gustave Flaubert","is_correct":true},{"id":"d","text":"Honoré de Balzac","is_correct":false}],"explanation":"Flaubert was tried for obscenity over Madame Bovary and acquitted in 1857."},{"id":"q7","question":"War and Peace, set during Napoleon''s invasion of Russia, was written by?","options":[{"id":"a","text":"Fyodor Dostoevsky","is_correct":false},{"id":"b","text":"Leo Tolstoy","is_correct":true},{"id":"c","text":"Ivan Turgenev","is_correct":false},{"id":"d","text":"Anton Chekhov","is_correct":false}],"explanation":"Tolstoy published War and Peace between 1865 and 1869."},{"id":"q8","question":"Which Brontë sister wrote Jane Eyre (1847) under the pen name Currer Bell?","options":[{"id":"a","text":"Emily Brontë","is_correct":false},{"id":"b","text":"Anne Brontë","is_correct":false},{"id":"c","text":"Charlotte Brontë","is_correct":true},{"id":"d","text":"Elizabeth Gaskell","is_correct":false}],"explanation":"Charlotte Brontë published Jane Eyre as Currer Bell; Emily wrote Wuthering Heights the same year."}]'::jsonb,
  null,
  array['literature', 'trivia', 'classic novels', 'canon']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
