values (
  'es-trivia-novelas-clasicas',
  'Trivia de novelas clásicas: del Quijote a Jane Eyre',
  'Ocho preguntas sobre las novelas que construyeron el canon: el Quijote, Orgullo y prejuicio, Moby-Dick, Crimen y castigo y más.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"¿Quién escribió Don Quijote, la novela fundacional de la literatura moderna?","options":[{"id":"a","text":"Lope de Vega","is_correct":false},{"id":"b","text":"Miguel de Cervantes","is_correct":true},{"id":"c","text":"Calderón de la Barca","is_correct":false},{"id":"d","text":"Tirso de Molina","is_correct":false}],"explanation":"Cervantes publicó la primera parte del Quijote en 1605 y la segunda en 1615."},{"id":"q2","question":"¿En qué año se publicó la primera parte del Quijote?","options":[{"id":"a","text":"1595","is_correct":false},{"id":"b","text":"1605","is_correct":true},{"id":"c","text":"1615","is_correct":false},{"id":"d","text":"1620","is_correct":false}],"explanation":"La primera parte apareció en 1605; la segunda llegó una década después, en 1615."},{"id":"q3","question":"¿Qué autora inglesa escribió Orgullo y prejuicio, publicada en 1813?","options":[{"id":"a","text":"Charlotte Brontë","is_correct":false},{"id":"b","text":"Mary Shelley","is_correct":false},{"id":"c","text":"Jane Austen","is_correct":true},{"id":"d","text":"Emily Brontë","is_correct":false}],"explanation":"Austen publicó la novela anónimamente, «por una dama»; su nombre se hizo público tras su muerte."},{"id":"q4","question":"¿Quién escribió Moby-Dick, la novela de 1851 sobre la obsesión del capitán Ahab por la ballena blanca?","options":[{"id":"a","text":"Nathaniel Hawthorne","is_correct":false},{"id":"b","text":"Herman Melville","is_correct":true},{"id":"c","text":"Edgar Allan Poe","is_correct":false},{"id":"d","text":"Mark Twain","is_correct":false}],"explanation":"Melville se basó en sus propios viajes balleneros; la novela vendió poco durante su vida."},{"id":"q5","question":"En Crimen y castigo (1866), de Dostoievski, ¿cómo se llama el estudiante que comete el asesinato?","options":[{"id":"a","text":"Raskólnikov","is_correct":true},{"id":"b","text":"El príncipe Myshkin","is_correct":false},{"id":"c","text":"Nikolái Stavroguin","is_correct":false},{"id":"d","text":"Aliosha Karamázov","is_correct":false}],"explanation":"Raskólnikov asesina a una prestamista en San Petersburgo; Myshkin es el héroe de El idiota."},{"id":"q6","question":"¿Qué autor francés escribió Madame Bovary (1856)?","options":[{"id":"a","text":"Victor Hugo","is_correct":false},{"id":"b","text":"Émile Zola","is_correct":false},{"id":"c","text":"Gustave Flaubert","is_correct":true},{"id":"d","text":"Honoré de Balzac","is_correct":false}],"explanation":"Flaubert fue juzgado por inmoralidad a causa de Madame Bovary y absuelto en 1857."},{"id":"q7","question":"Guerra y paz, ambientada durante la invasión napoleónica de Rusia, fue escrita por?","options":[{"id":"a","text":"Fiódor Dostoievski","is_correct":false},{"id":"b","text":"León Tolstói","is_correct":true},{"id":"c","text":"Iván Turguéniev","is_correct":false},{"id":"d","text":"Antón Chéjov","is_correct":false}],"explanation":"Tolstói publicó Guerra y paz entre 1865 y 1869."},{"id":"q8","question":"¿Qué hermana Brontë escribió Jane Eyre (1847) bajo el seudónimo de Currer Bell?","options":[{"id":"a","text":"Emily Brontë","is_correct":false},{"id":"b","text":"Anne Brontë","is_correct":false},{"id":"c","text":"Charlotte Brontë","is_correct":true},{"id":"d","text":"Elizabeth Gaskell","is_correct":false}],"explanation":"Charlotte publicó Jane Eyre como Currer Bell; Emily escribió Cumbres borrascosas ese mismo año."}]'::jsonb,
  null,
  array['literatura', 'trivia', 'novelas clásicas', 'canon']::text[],
  3,
  'published',
