insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-books-that-became-movies-trivia',
  'Books That Became Movies Trivia: From Page to Screen',
  'Eight questions on the novels behind famous films: The Godfather, Jurassic Park, The Lord of the Rings, Dune and more.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"The Godfather (1972) is based on a novel by which author?","options":[{"id":"a","text":"Mario Puzo","is_correct":true},{"id":"b","text":"Norman Mailer","is_correct":false},{"id":"c","text":"Truman Capote","is_correct":false},{"id":"d","text":"Tom Clancy","is_correct":false}],"explanation":"Puzo published The Godfather in 1969 and co-wrote the Oscar-winning screenplay with Coppola."},{"id":"q2","question":"Which author wrote the novel Jurassic Park (1990) that Spielberg adapted in 1993?","options":[{"id":"a","text":"Arthur C. Clarke","is_correct":false},{"id":"b","text":"Michael Crichton","is_correct":true},{"id":"c","text":"Stephen King","is_correct":false},{"id":"d","text":"James Patterson","is_correct":false}],"explanation":"Crichton trained as a doctor at Harvard and also created the TV series ER."},{"id":"q3","question":"The Lord of the Rings film trilogy adapts the work of which writer?","options":[{"id":"a","text":"C. S. Lewis","is_correct":false},{"id":"b","text":"George R. R. Martin","is_correct":false},{"id":"c","text":"J. R. R. Tolkien","is_correct":true},{"id":"d","text":"Ursula K. Le Guin","is_correct":false}],"explanation":"Tolkien published the three volumes of The Lord of the Rings in 1954 and 1955."},{"id":"q4","question":"Who directed The Lord of the Rings film trilogy (2001-2003)?","options":[{"id":"a","text":"Ridley Scott","is_correct":false},{"id":"b","text":"Peter Jackson","is_correct":true},{"id":"c","text":"Steven Spielberg","is_correct":false},{"id":"d","text":"Guillermo del Toro","is_correct":false}],"explanation":"Jackson shot the three films back to back in New Zealand."},{"id":"q5","question":"The first Harry Potter film (2001) adapts which novel?","options":[{"id":"a","text":"Harry Potter and the Chamber of Secrets","is_correct":false},{"id":"b","text":"Harry Potter and the Philosopher''s Stone","is_correct":true},{"id":"c","text":"Harry Potter and the Prisoner of Azkaban","is_correct":false},{"id":"d","text":"Harry Potter and the Goblet of Fire","is_correct":false}],"explanation":"J. K. Rowling published The Philosopher''s Stone in 1997; the film premiered in 2001."},{"id":"q6","question":"The Shawshank Redemption (1994) is based on a novella by which author?","options":[{"id":"a","text":"John Grisham","is_correct":false},{"id":"b","text":"Dean Koontz","is_correct":false},{"id":"c","text":"Michael Connelly","is_correct":false},{"id":"d","text":"Stephen King","is_correct":true}],"explanation":"It adapts Rita Hayworth and Shawshank Redemption, from the 1982 collection Different Seasons."},{"id":"q7","question":"Blade Runner (1982) is based on a novel by which science fiction author?","options":[{"id":"a","text":"Isaac Asimov","is_correct":false},{"id":"b","text":"Philip K. Dick","is_correct":true},{"id":"c","text":"William Gibson","is_correct":false},{"id":"d","text":"Ray Bradbury","is_correct":false}],"explanation":"The film adapts Do Androids Dream of Electric Sheep?, published by Dick in 1968."},{"id":"q8","question":"Who directed the 1984 film adaptation of Frank Herbert''s Dune?","options":[{"id":"a","text":"David Lynch","is_correct":true},{"id":"b","text":"Denis Villeneuve","is_correct":false},{"id":"c","text":"Alejandro Jodorowsky","is_correct":false},{"id":"d","text":"Ridley Scott","is_correct":false}],"explanation":"Lynch directed the 1984 version; Villeneuve''s adaptation arrived in 2021."}]'::jsonb,
  null,
  array['literature', 'trivia', 'books', 'movies', 'adaptations']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

