  '[{"id":"q1","question":"El padrino (1972) está basada en una novela de qué autor?","options":[{"id":"a","text":"Mario Puzo","is_correct":true},{"id":"b","text":"Norman Mailer","is_correct":false},{"id":"c","text":"Truman Capote","is_correct":false},{"id":"d","text":"Tom Clancy","is_correct":false}],"explanation":"Puzo publicó El padrino en 1969 y coescribió con Coppola el guion que ganó el Óscar."},{"id":"q2","question":"¿Qué autor escribió la novela Jurassic Park (1990) que Spielberg adaptó en 1993?","options":[{"id":"a","text":"Arthur C. Clarke","is_correct":false},{"id":"b","text":"Michael Crichton","is_correct":true},{"id":"c","text":"Stephen King","is_correct":false},{"id":"d","text":"James Patterson","is_correct":false}],"explanation":"Crichton se formó como médico en Harvard y también creó la serie Urgencias (ER)."},{"id":"q3","question":"La trilogía cinematográfica de El señor de los anillos adapta la obra de qué escritor?","options":[{"id":"a","text":"C. S. Lewis","is_correct":false},{"id":"b","text":"George R. R. Martin","is_correct":false},{"id":"c","text":"J. R. R. Tolkien","is_correct":true},{"id":"d","text":"Ursula K. Le Guin","is_correct":false}],"explanation":"Tolkien publicó los tres volúmenes de El señor de los anillos en 1954 y 1955."},{"id":"q4","question":"¿Quién dirigió la trilogía de El señor de los anillos (2001-2003)?","options":[{"id":"a","text":"Ridley Scott","is_correct":false},{"id":"b","text":"Peter Jackson","is_correct":true},{"id":"c","text":"Steven Spielberg","is_correct":false},{"id":"d","text":"Guillermo del Toro","is_correct":false}],"explanation":"Jackson rodó las tres películas seguidas en Nueva Zelanda."},{"id":"q5","question":"La primera película de Harry Potter (2001) adapta qué novela?","options":[{"id":"a","text":"Harry Potter y la cámara secreta","is_correct":false},{"id":"b","text":"Harry Potter y la piedra filosofal","is_correct":true},{"id":"c","text":"Harry Potter y el prisionero de Azkaban","is_correct":false},{"id":"d","text":"Harry Potter y el cáliz de fuego","is_correct":false}],"explanation":"J. K. Rowling publicó La piedra filosofal en 1997; la película se estrenó en 2001."},{"id":"q6","question":"Sueños de libertad (The Shawshank Redemption, 1994) se basa en una novela corta de qué autor?","options":[{"id":"a","text":"John Grisham","is_correct":false},{"id":"b","text":"Dean Koontz","is_correct":false},{"id":"c","text":"Michael Connelly","is_correct":false},{"id":"d","text":"Stephen King","is_correct":true}],"explanation":"Adapta Rita Hayworth and Shawshank Redemption, del libro Different Seasons (1982)."},{"id":"q7","question":"Blade Runner (1982) se basa en una novela de qué autor de ciencia ficción?","options":[{"id":"a","text":"Isaac Asimov","is_correct":false},{"id":"b","text":"Philip K. Dick","is_correct":true},{"id":"c","text":"William Gibson","is_correct":false},{"id":"d","text":"Ray Bradbury","is_correct":false}],"explanation":"La película adapta ¿Sueñan los androides con ovejas eléctricas?, publicada por Dick en 1968."},{"id":"q8","question":"¿Quién dirigió la adaptación cinematográfica de Dune estrenada en 1984?","options":[{"id":"a","text":"David Lynch","is_correct":true},{"id":"b","text":"Denis Villeneuve","is_correct":false},{"id":"c","text":"Alejandro Jodorowsky","is_correct":false},{"id":"d","text":"Ridley Scott","is_correct":false}],"explanation":"Lynch dirigió la versión de 1984; la adaptación de Villeneuve llegó en 2021."}]'::jsonb,
