insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-science-fiction-books-trivia',
  'Science Fiction Books Trivia: Classics That Saw the Future',
  'Eight questions on the classics of science fiction: Frankenstein, 1984, Fahrenheit 451, Foundation, Dune and more.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"Who wrote Frankenstein, often called the first science fiction novel?","options":[{"id":"a","text":"Bram Stoker","is_correct":false},{"id":"b","text":"Mary Shelley","is_correct":true},{"id":"c","text":"Percy Shelley","is_correct":false},{"id":"d","text":"Jane Austen","is_correct":false}],"explanation":"Mary Shelley conceived the story in 1816 during a famous contest at Villa Diodati."},{"id":"q2","question":"In which year was Frankenstein first published?","options":[{"id":"a","text":"1798","is_correct":false},{"id":"b","text":"1818","is_correct":true},{"id":"c","text":"1823","is_correct":false},{"id":"d","text":"1831","is_correct":false}],"explanation":"It appeared anonymously in 1818; the revised edition with Shelley''s name came in 1831."},{"id":"q3","question":"The Time Machine (1895), the novel that popularized time travel, was written by?","options":[{"id":"a","text":"Jules Verne","is_correct":false},{"id":"b","text":"Aldous Huxley","is_correct":false},{"id":"c","text":"H. G. Wells","is_correct":true},{"id":"d","text":"Isaac Asimov","is_correct":false}],"explanation":"Wells''s traveler journeys to the year 802,701 and meets the Eloi and the Morlocks."},{"id":"q4","question":"Which author wrote the dystopia 1984, published in 1949?","options":[{"id":"a","text":"Aldous Huxley","is_correct":false},{"id":"b","text":"George Orwell","is_correct":true},{"id":"c","text":"Ray Bradbury","is_correct":false},{"id":"d","text":"Philip K. Dick","is_correct":false}],"explanation":"Orwell died of tuberculosis in 1950, months after the novel appeared."},{"id":"q5","question":"In Fahrenheit 451, what is the job of ''firemen'' like Guy Montag?","options":[{"id":"a","text":"Putting out fires","is_correct":false},{"id":"b","text":"Guarding libraries","is_correct":false},{"id":"c","text":"Burning books","is_correct":true},{"id":"d","text":"Censoring newspapers","is_correct":false}],"explanation":"Bradbury''s firemen burn books; the title is the temperature at which paper catches fire."},{"id":"q6","question":"Who wrote Fahrenheit 451 (1953)?","options":[{"id":"a","text":"Ray Bradbury","is_correct":true},{"id":"b","text":"Kurt Vonnegut","is_correct":false},{"id":"c","text":"Ursula K. Le Guin","is_correct":false},{"id":"d","text":"Robert A. Heinlein","is_correct":false}],"explanation":"Bradbury wrote it on rented typewriters in the basement of UCLA''s library."},{"id":"q7","question":"Foundation (1951), about a mathematician who foresees the fall of a galactic empire, is by?","options":[{"id":"a","text":"Arthur C. Clarke","is_correct":false},{"id":"b","text":"Frank Herbert","is_correct":false},{"id":"c","text":"Isaac Asimov","is_correct":true},{"id":"d","text":"Robert A. Heinlein","is_correct":false}],"explanation":"Asimov''s Hari Seldon uses ''psychohistory'' to shorten the coming dark age."},{"id":"q8","question":"In Frank Herbert''s Dune (1965), what is the name of the desert planet where the story unfolds?","options":[{"id":"a","text":"Arrakis","is_correct":true},{"id":"b","text":"Caladan","is_correct":false},{"id":"c","text":"Giedi Prime","is_correct":false},{"id":"d","text":"Kaitain","is_correct":false}],"explanation":"Arrakis is the only source of the spice melange; Caladan is the rainy home world of the Atreides."}]'::jsonb,
  null,
  array['literature', 'trivia', 'science fiction', 'dystopia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

