insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-poetry-trivia',
  'Poetry Trivia: Sonnets, Haiku and Nobel Laureates',
  'Eight questions on poetry: the sonnet and Petrarch, Bashō''s haiku, and the verses of Neruda, Lorca, Mistral and Borges.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"How many lines does a sonnet have?","options":[{"id":"a","text":"10","is_correct":false},{"id":"b","text":"12","is_correct":false},{"id":"c","text":"14","is_correct":true},{"id":"d","text":"16","is_correct":false}],"explanation":"A sonnet has 14 lines, usually split into two quatrains and two tercets."},{"id":"q2","question":"The ''Petrarchan sonnet'' is named after which Italian poet?","options":[{"id":"a","text":"Dante Alighieri","is_correct":false},{"id":"b","text":"Francesco Petrarca","is_correct":true},{"id":"c","text":"Giovanni Boccaccio","is_correct":false},{"id":"d","text":"Giacomo Leopardi","is_correct":false}],"explanation":"Petrarca dedicated hundreds of sonnets to Laura in the 14th century."},{"id":"q3","question":"How many syllables does a traditional Japanese haiku have?","options":[{"id":"a","text":"14","is_correct":false},{"id":"b","text":"17","is_correct":true},{"id":"c","text":"19","is_correct":false},{"id":"d","text":"21","is_correct":false}],"explanation":"A haiku is built in three lines of five, seven and five syllables."},{"id":"q4","question":"Which 17th-century Japanese poet is considered the master of the haiku?","options":[{"id":"a","text":"Murasaki Shikibu","is_correct":false},{"id":"b","text":"Matsuo Bashō","is_correct":true},{"id":"c","text":"Yukio Mishima","is_correct":false},{"id":"d","text":"Ryūnosuke Akutagawa","is_correct":false}],"explanation":"Bashō raised the haiku to literary art in the Edo period; his poem about a frog in a pond is the most famous."},{"id":"q5","question":"Which Chilean poet published Twenty Love Poems and a Song of Despair in 1924, at age nineteen?","options":[{"id":"a","text":"Vicente Huidobro","is_correct":false},{"id":"b","text":"César Vallejo","is_correct":false},{"id":"c","text":"Pablo Neruda","is_correct":true},{"id":"d","text":"Gabriela Mistral","is_correct":false}],"explanation":"Neruda was nineteen when the book appeared under his pen name; his real name was Neftalí Reyes."},{"id":"q6","question":"Which 1928 collection made Federico García Lorca famous across Spain?","options":[{"id":"a","text":"Gypsy Ballads (Romancero gitano)","is_correct":true},{"id":"b","text":"Poet in New York","is_correct":false},{"id":"c","text":"Lament for Ignacio Sánchez Mejías","is_correct":false},{"id":"d","text":"Diván del Tamarit","is_correct":false}],"explanation":"Romancero gitano appeared in 1928; Poet in New York was published after his death, in 1940."},{"id":"q7","question":"Who was the first Latin American author to win the Nobel Prize in Literature?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Miguel Ángel Asturias","is_correct":false},{"id":"c","text":"Jorge Luis Borges","is_correct":false},{"id":"d","text":"Gabriela Mistral","is_correct":true}],"explanation":"Mistral won in 1945; Borges, despite decades of nominations, never received it."},{"id":"q8","question":"Ficciones (1944) and The Aleph (1949) are works by which Argentine poet and storyteller?","options":[{"id":"a","text":"Julio Cortázar","is_correct":false},{"id":"b","text":"Jorge Luis Borges","is_correct":true},{"id":"c","text":"Adolfo Bioy Casares","is_correct":false},{"id":"d","text":"Leopoldo Lugones","is_correct":false}],"explanation":"Borges directed Argentina''s National Library and shared the Cervantes Prize in 1979."}]'::jsonb,
  null,
  array['literature', 'trivia', 'poetry', 'poets']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-poesia',
  'Trivia de poesía: sonetos, haikus y premios Nobel',
  'Ocho preguntas sobre poesía: el soneto de Petrarca, el haiku de Bashō y los versos de Neruda, Lorca, Mistral y Borges.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"¿Cuántos versos tiene un soneto?","options":[{"id":"a","text":"10","is_correct":false},{"id":"b","text":"12","is_correct":false},{"id":"c","text":"14","is_correct":true},{"id":"d","text":"16","is_correct":false}],"explanation":"Un soneto tiene 14 versos, repartidos por lo general en dos cuartetos y dos tercetos."},{"id":"q2","question":"El «soneto petrarquista» lleva el nombre de qué poeta italiano?","options":[{"id":"a","text":"Dante Alighieri","is_correct":false},{"id":"b","text":"Francesco Petrarca","is_correct":true},{"id":"c","text":"Giovanni Boccaccio","is_correct":false},{"id":"d","text":"Giacomo Leopardi","is_correct":false}],"explanation":"Petrarca dedicó cientos de sonetos a Laura en el siglo XIV."},{"id":"q3","question":"¿Cuántas sílabas tiene un haiku japonés tradicional?","options":[{"id":"a","text":"14","is_correct":false},{"id":"b","text":"17","is_correct":true},{"id":"c","text":"19","is_correct":false},{"id":"d","text":"21","is_correct":false}],"explanation":"El haiku se construye en tres versos de cinco, siete y cinco sílabas."},{"id":"q4","question":"¿Qué poeta japonés del siglo XVII es considerado el maestro del haiku?","options":[{"id":"a","text":"Murasaki Shikibu","is_correct":false},{"id":"b","text":"Matsuo Bashō","is_correct":true},{"id":"c","text":"Yukio Mishima","is_correct":false},{"id":"d","text":"Ryūnosuke Akutagawa","is_correct":false}],"explanation":"Bashō elevó el haiku a arte literario en el periodo Edo; su poema de la rana en el estanque es el más famoso."},{"id":"q5","question":"¿Qué poeta chileno publicó Veinte poemas de amor y una canción desesperada en 1924, a los diecinueve años?","options":[{"id":"a","text":"Vicente Huidobro","is_correct":false},{"id":"b","text":"César Vallejo","is_correct":false},{"id":"c","text":"Pablo Neruda","is_correct":true},{"id":"d","text":"Gabriela Mistral","is_correct":false}],"explanation":"Neruda tenía diecinueve años cuando apareció el libro bajo su seudónimo; su nombre real era Neftalí Reyes."},{"id":"q6","question":"¿Qué libro de 1928 hizo famoso a Federico García Lorca en toda España?","options":[{"id":"a","text":"Romancero gitano","is_correct":true},{"id":"b","text":"Poeta en Nueva York","is_correct":false},{"id":"c","text":"Llanto por Ignacio Sánchez Mejías","is_correct":false},{"id":"d","text":"Diván del Tamarit","is_correct":false}],"explanation":"El Romancero gitano apareció en 1928; Poeta en Nueva York se publicó tras su muerte, en 1940."},{"id":"q7","question":"¿Quién fue el primer autor latinoamericano en ganar el Nobel de Literatura?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Miguel Ángel Asturias","is_correct":false},{"id":"c","text":"Jorge Luis Borges","is_correct":false},{"id":"d","text":"Gabriela Mistral","is_correct":true}],"explanation":"Mistral ganó en 1945; Borges, pese a décadas de candidaturas, nunca lo recibió."},{"id":"q8","question":"Ficciones (1944) y El Aleph (1949) son obras de qué poeta y cuentista argentino?","options":[{"id":"a","text":"Julio Cortázar","is_correct":false},{"id":"b","text":"Jorge Luis Borges","is_correct":true},{"id":"c","text":"Adolfo Bioy Casares","is_correct":false},{"id":"d","text":"Leopoldo Lugones","is_correct":false}],"explanation":"Borges dirigió la Biblioteca Nacional de Argentina y ganó el Premio Cervantes en 1979."}]'::jsonb,
  null,
  array['literatura', 'trivia', 'poesía', 'poetas']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-nobel-literature-trivia',
  'Nobel Prize in Literature Trivia: A Century of Laureates',
  'Eight questions on the Nobel Prize in Literature, from Sully Prudhomme in 1901 to Mistral, García Márquez and Dylan.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"In which year was the Nobel Prize in Literature first awarded?","options":[{"id":"a","text":"1895","is_correct":false},{"id":"b","text":"1901","is_correct":true},{"id":"c","text":"1905","is_correct":false},{"id":"d","text":"1910","is_correct":false}],"explanation":"The first Nobel Prizes were awarded in 1901, five years after Alfred Nobel''s death."},{"id":"q2","question":"Who received the first Nobel Prize in Literature?","options":[{"id":"a","text":"Rudyard Kipling","is_correct":false},{"id":"b","text":"Rabindranath Tagore","is_correct":false},{"id":"c","text":"Sully Prudhomme","is_correct":true},{"id":"d","text":"Henryk Sienkiewicz","is_correct":false}],"explanation":"The French poet Sully Prudhomme won in 1901; Kipling, Tagore and Sienkiewicz followed in later years."},{"id":"q3","question":"Who was the first woman to win the Nobel Prize in Literature?","options":[{"id":"a","text":"Gabriela Mistral","is_correct":false},{"id":"b","text":"Selma Lagerlöf","is_correct":true},{"id":"c","text":"Pearl S. Buck","is_correct":false},{"id":"d","text":"Grazia Deledda","is_correct":false}],"explanation":"The Swedish writer Selma Lagerlöf won in 1909."},{"id":"q4","question":"Which Chilean poet won the Nobel in 1945, the first Latin American laureate?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Vicente Huidobro","is_correct":false},{"id":"c","text":"Gabriela Mistral","is_correct":true},{"id":"d","text":"Nicanor Parra","is_correct":false}],"explanation":"Mistral, a teacher and diplomat, was the first Latin American author to receive the prize."},{"id":"q5","question":"In which year did Pablo Neruda win the Nobel Prize in Literature?","options":[{"id":"a","text":"1964","is_correct":false},{"id":"b","text":"1967","is_correct":false},{"id":"c","text":"1971","is_correct":true},{"id":"d","text":"1975","is_correct":false}],"explanation":"Neruda won in 1971, twenty-six years after his compatriot Gabriela Mistral."},{"id":"q6","question":"Gabriel García Márquez, author of One Hundred Years of Solitude, won the Nobel in?","options":[{"id":"a","text":"1979","is_correct":false},{"id":"b","text":"1982","is_correct":true},{"id":"c","text":"1985","is_correct":false},{"id":"d","text":"1989","is_correct":false}],"explanation":"He won in 1982, the first Colombian to receive a Nobel Prize."},{"id":"q7","question":"In which year did Mario Vargas Llosa win the Nobel Prize in Literature?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2008","is_correct":false},{"id":"c","text":"2010","is_correct":true},{"id":"d","text":"2012","is_correct":false}],"explanation":"The Peruvian novelist won in 2010 for ''his cartography of structures of power''."},{"id":"q8","question":"Which singer-songwriter received the Nobel Prize in Literature in 2016?","options":[{"id":"a","text":"Leonard Cohen","is_correct":false},{"id":"b","text":"Paul McCartney","is_correct":false},{"id":"c","text":"Bruce Springsteen","is_correct":false},{"id":"d","text":"Bob Dylan","is_correct":true}],"explanation":"Dylan won ''for having created new poetic expressions within the great American song tradition''."}]'::jsonb,
  null,
  array['literature', 'trivia', 'nobel prize', 'laureates']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-premios-nobel-de-literatura',
  'Trivia de premios Nobel de Literatura: un siglo de laureados',
  'Ocho preguntas sobre el Nobel de Literatura, de Sully Prudhomme en 1901 a Mistral, García Márquez y Dylan.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"¿En qué año se entregó por primera vez el Premio Nobel de Literatura?","options":[{"id":"a","text":"1895","is_correct":false},{"id":"b","text":"1901","is_correct":true},{"id":"c","text":"1905","is_correct":false},{"id":"d","text":"1910","is_correct":false}],"explanation":"Los primeros premios Nobel se entregaron en 1901, cinco años después de la muerte de Alfred Nobel."},{"id":"q2","question":"¿Quién recibió el primer Premio Nobel de Literatura?","options":[{"id":"a","text":"Rudyard Kipling","is_correct":false},{"id":"b","text":"Rabindranath Tagore","is_correct":false},{"id":"c","text":"Sully Prudhomme","is_correct":true},{"id":"d","text":"Henryk Sienkiewicz","is_correct":false}],"explanation":"El poeta francés Sully Prudhomme ganó en 1901; Kipling, Tagore y Sienkiewicz llegaron después."},{"id":"q3","question":"¿Quién fue la primera mujer en ganar el Premio Nobel de Literatura?","options":[{"id":"a","text":"Gabriela Mistral","is_correct":false},{"id":"b","text":"Selma Lagerlöf","is_correct":true},{"id":"c","text":"Pearl S. Buck","is_correct":false},{"id":"d","text":"Grazia Deledda","is_correct":false}],"explanation":"La escritora sueca Selma Lagerlöf ganó en 1909."},{"id":"q4","question":"¿Qué poeta chilena ganó el Nobel en 1945, primera laureada latinoamericana?","options":[{"id":"a","text":"Pablo Neruda","is_correct":false},{"id":"b","text":"Vicente Huidobro","is_correct":false},{"id":"c","text":"Gabriela Mistral","is_correct":true},{"id":"d","text":"Nicanor Parra","is_correct":false}],"explanation":"Mistral, maestra y diplomática, fue la primera autora latinoamericana en recibir el premio."},{"id":"q5","question":"¿En qué año ganó Pablo Neruda el Premio Nobel de Literatura?","options":[{"id":"a","text":"1964","is_correct":false},{"id":"b","text":"1967","is_correct":false},{"id":"c","text":"1971","is_correct":true},{"id":"d","text":"1975","is_correct":false}],"explanation":"Neruda ganó en 1971, veintiséis años después de su compatriota Gabriela Mistral."},{"id":"q6","question":"Gabriel García Márquez, autor de Cien años de soledad, ganó el Nobel en?","options":[{"id":"a","text":"1979","is_correct":false},{"id":"b","text":"1982","is_correct":true},{"id":"c","text":"1985","is_correct":false},{"id":"d","text":"1989","is_correct":false}],"explanation":"Ganó en 1982, el primer colombiano en recibir un premio Nobel."},{"id":"q7","question":"¿En qué año ganó Mario Vargas Llosa el Premio Nobel de Literatura?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2008","is_correct":false},{"id":"c","text":"2010","is_correct":true},{"id":"d","text":"2012","is_correct":false}],"explanation":"El novelista peruano ganó en 2010 por su «cartografía de las estructuras del poder»."},{"id":"q8","question":"¿Qué cantautor recibió el Premio Nobel de Literatura en 2016?","options":[{"id":"a","text":"Leonard Cohen","is_correct":false},{"id":"b","text":"Paul McCartney","is_correct":false},{"id":"c","text":"Bruce Springsteen","is_correct":false},{"id":"d","text":"Bob Dylan","is_correct":true}],"explanation":"Dylan ganó por «haber creado nuevas expresiones poéticas dentro de la gran tradición de la canción estadounidense»."}]'::jsonb,
  null,
  array['literatura', 'trivia', 'premio nobel', 'laureados']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

